// Change the text before each run; keep the same id to continue the same cart.
return [{
  json: {
    messaging: [
      {
        sender: { id: 'TEST-1' },
        message: { mid: 'test', text: 'hi' }
      }
    ]
  }
}];

// One item per real customer text. Skips our own echoes, reactions and read receipts.
const platform = ($prevNode?.name || '').includes('Instagram') ? 'Instagram' : 'Messenger';
const out = [];
for (const item of $input.all()) {
  for (const m of (item.json.messaging || [])) {
    if (!m.message || m.message.is_echo || !m.message.text) continue;
    out.push({
      json: {
        platform,
        sender_id: String(m.sender.id),
        text: String(m.message.text).slice(0, 1000)
      }
    });
  }
}
return out.slice(0, 1);

const msg = $('Read Message').first().json;
const menu = $('Read Menu').all().map(i => i.json).filter(m => String(m.item_id || '').trim());
const cartRow = $('Find Cart').all().map(i => i.json).find(
  r => String(r.customer_id) === msg.sender_id && r.status === 'open'
);

const prompt = [
  'You take orders for Fenjan, a café in Cairo, over Messenger and Instagram DMs. Customers write in Egyptian Arabic, English or Franco-Arabic (e.g. "3ayez 2 latte").',
  'Return ONLY JSON: {"intent":"greeting|menu|order|details|confirm|cancel|question|human","items":[{"item_id":"D01","qty":1}],"remove":["D01"],"replace_cart":false,"fulfilment":"pickup|delivery|","address":"","language":"ar|en","answer":""}',
  'intent rules: "order" = adding or changing items (put them in items, use only item_id values from MENU, map nicknames using the words field). "remove" lists items to take out. replace_cart=true only if the customer clearly starts a new order.',
  '"details" = only says pickup/delivery or gives an address. "confirm" = agrees to place the current cart (yes, ok, confirm, تمام, أكد, ماشي). "cancel" = wants to cancel. "human" = complaint, problem, or asks for a person. "menu" = asks what you have or prices. "greeting" = only hello.',
  '"question" = anything else: write a short friendly answer (max 2 sentences, same language, only facts from MENU) in answer. Never invent items or prices. fulfilment and address can be filled with any intent if mentioned. language = ar if the customer writes Arabic or Franco, else en.',
  'MENU: ' + JSON.stringify(menu.map(m => ({
    id: m.item_id,
    en: m.name_en,
    ar: m.name_ar,
    price: m.price_egp,
    available: m.available,
    words: m.keywords
  }))),
  'CURRENT CART: ' + (cartRow ? cartRow.items_json : '[]') + ' | fulfilment: ' + (cartRow?.fulfilment || 'unknown'),
  'CUSTOMER MESSAGE: ' + msg.text,
].join('\n');

return [{ json: { prompt } }];

// The AI only reads the message. Items, prices and totals always come from the Menu sheet.
const DELIVERY_FEE = 25, OPEN_HOUR = 8, CLOSE_HOUR = 24, MAX_QTY = 20;
const msg = $('Read Message').first().json;
const menu = $('Read Menu').all().map(i => i.json).filter(m => String(m.item_id || '').trim());
const byId = Object.fromEntries(menu.map(m => [String(m.item_id).trim().toUpperCase(), m]));
const isOn = m => /^(yes|true|1|y)$/i.test(String(m.available ?? 'yes').trim());
const cartRow = $('Find Cart').all().map(i => i.json).find(
  r => String(r.customer_id) === msg.sender_id && r.status === 'open'
);

let cart = [];
try {
  cart = cartRow ? JSON.parse(cartRow.items_json || '[]') : [];
} catch (e) {
  cart = [];
}

let fulfilment = cartRow?.fulfilment || '', address = cartRow?.address || '';
let ai = null;
try {
  const raw = ($json.candidates?.[0]?.content?.parts || [])
    .map(p => p.text)
    .join('')
    .replace(/^```json\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  ai = raw ? JSON.parse(raw) : null;
} catch (e) {
  ai = null;
}

const ar = ai ? ai.language === 'ar' : /[\u0600-\u06FF]/.test(msg.text);
const t = (en, a) => ar ? a : en;
const EGP = t('EGP', 'ج.م');

if (ai && ['pickup', 'delivery'].includes(ai.fulfilment)) fulfilment = ai.fulfilment;
if (ai && String(ai.address || '').trim().length > 5) address = String(ai.address).trim().slice(0, 200);

const sub = () => cart.reduce((s, l) => s + l.qty * l.price, 0);
const fee = () => fulfilment === 'delivery' ? DELIVERY_FEE : 0;

const cartText = () =>
  cart.map(l => `${l.qty} × ${ar ? l.name_ar : l.name} — ${l.qty * l.price} ${EGP}`).join('\n')
  + (fee() ? `\n${t('Delivery', 'التوصيل')} — ${fee()} ${EGP}` : '')
  + `\n${t('Total', 'الإجمالي')}: ${sub() + fee()} ${EGP}`;

const menuText = () => {
  const cats = {};
  for (const m of menu.filter(isOn)) {
    (cats[m.category] = cats[m.category] || []).push(`${m.item_id} · ${ar ? m.name_ar : m.name_en} — ${m.price_egp}`);
  }
  return t('☕ Fenjan menu (EGP)', '☕ منيو فنجان (بالجنيه)')
    + Object.entries(cats).map(([c, l]) => `\n\n${c}\n` + l.join('\n')).join('')
    + t('\n\nJust type your order, e.g. "2 spanish latte and a croissant, delivery".', '\n\nاكتب طلبك، مثلاً: "٢ سبانش لاتيه وكرواسون، توصيل".');
};

const nextStep = () =>
  !fulfilment
    ? t('Pickup or delivery?', 'استلام من المحل ولا توصيل؟')
    : fulfilment === 'delivery' && !address
      ? t('Please send your delivery address.', 'ابعتلي عنوان التوصيل.')
      : t('Reply "confirm" to place your order.', 'اكتب "تأكيد" عشان نبدأ نحضر طلبك.');

const hour = Number($now.setZone('Africa/Cairo').toFormat('H'));
const isOpen = hour >= OPEN_HOUR && hour < CLOSE_HOUR;
const order_id = 'F-' + $now.setZone('Africa/Cairo').toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, 'X');

let action = 'reply', reply = '';
const notes = [];
const intent = ai?.intent;

if (!intent) {
  action = 'human';
  reply = t(
    "Sorry, I couldn't read that one. A team member will reply here shortly.",
    'معلش مقدرتش أفهم الرسالة دي. حد من الفريق هيرد عليك هنا حالاً.'
  );
} else if (intent === 'greeting' || intent === 'menu') {
  reply = (intent === 'greeting' ? t('Welcome to Fenjan! ☕\n\n', 'أهلاً بيك في فنجان! ☕\n\n') : '') + menuText();
} else if (intent === 'order' || intent === 'details') {
  if (ai.replace_cart) cart = [];
  for (const id of (ai.remove || [])) {
    cart = cart.filter(l => l.item_id !== String(id).trim().toUpperCase());
  }
  for (const it of (ai.items || [])) {
    const id = String(it.item_id || '').trim().toUpperCase();
    const m = byId[id];
    if (!m) {
      notes.push(t(`I couldn't find "${it.item_id}" on the menu.`, `مش لاقي "${it.item_id}" في المنيو.`));
      continue;
    }
    if (!isOn(m)) {
      notes.push(t(`${m.name_en} is not available today.`, `${m.name_ar} مش متاح النهاردة.`));
      continue;
    }
    const qty = Math.min(MAX_QTY, Math.max(1, parseInt(it.qty, 10) || 1));
    const ex = cart.find(l => l.item_id === id);
    if (ex) ex.qty = Math.min(MAX_QTY, ex.qty + qty);
    else cart.push({ item_id: id, name: m.name_en, name_ar: m.name_ar || m.name_en, price: Number(m.price_egp) || 0, qty });
  }
  if (!cart.length) {
    action = cartRow ? 'clear' : 'reply';
    reply = (notes.length ? notes.join('\n') + '\n\n' : '') + menuText();
  } else {
    action = 'cart';
    reply = (notes.length ? notes.join('\n') + '\n\n' : '') + t('Your order:\n', 'طلبك:\n') + cartText() + '\n\n' + nextStep();
  }
} else if (intent === 'confirm') {
  if (!cart.length) {
    reply = t('Your cart is empty. Tell me what you would like:\n\n', 'السلة فاضية، قولي تحب تطلب إيه:\n\n') + menuText();
  } else if (!fulfilment || (fulfilment === 'delivery' && !address)) {
    action = 'cart';
    reply = t('Almost there! ', 'خلاص قربنا! ') + nextStep();
  } else if (!isOpen) {
    action = 'cart';
    reply = t(
      `We are closed now (open ${OPEN_HOUR}:00 until midnight). Your cart is saved, confirm again when we open.`,
      `إحنا قافلين دلوقتي (بنفتح من ${OPEN_HOUR} الصبح لنص الليل). سلتك محفوظة، أكد تاني لما نفتح.`
    );
  } else {
    action = 'confirm';
    reply = t(`✅ Order ${order_id} confirmed!\n\n`, `✅ تم تأكيد طلبك ${order_id}!\n\n`)
      + cartText() + '\n\n'
      + (fulfilment === 'delivery'
        ? t(`Delivery to: ${address}\nWe will message you when it is on the way.`, `التوصيل على: ${address}\nهنبعتلك أول ما يخرج للتوصيل.`)
        : t('We will message you when it is ready for pickup.', 'هنبعتلك أول ما يجهز للاستلام.'));
  }
} else if (intent === 'cancel') {
  action = cartRow ? 'clear' : 'reply';
  reply = t('Done, your cart is cleared. Send anything to start again.', 'تمام، السلة اتمسحت. ابعت أي حاجة ونبدأ من جديد.');
} else if (intent === 'human') {
  action = 'human';
  reply = t('Sure, a team member will reply here shortly.', 'أكيد، حد من الفريق هيرد عليك هنا حالاً.');
} else {
  reply = (String(ai.answer || '').trim().slice(0, 600) || t('How can I help? Type "menu" to see what we have.', 'أقدر أساعدك إزاي؟ اكتب "منيو" تشوف عندنا إيه.'))
    + (cart.length ? '\n\n' + t('Your cart:\n', 'سلتك:\n') + cartText() + '\n\n' + nextStep() : '');
}

return [{
  json: {
    action,
    reply: reply.slice(0, 1980),
    platform: msg.platform,
    sender_id: msg.sender_id,
    text: msg.text,
    language: ar ? 'ar' : 'en',
    order_id,
    items_json: JSON.stringify(cart),
    items_text: cart.map(l => `${l.qty} × ${l.name}`).join(', '),
    subtotal: sub(),
    delivery: fee(),
    total: sub() + fee(),
    fulfilment,
    address,
    now: $now.setZone('Africa/Cairo').toFormat('yyyy-MM-dd HH:mm'),
  }
}];

const d = $('Decide Reply').first().json;
return [{
  json: {
    order_id: d.order_id,
    created_at: d.now,
    platform: d.platform,
    customer_id: d.sender_id,
    language: d.language,
    items: d.items_text,
    subtotal_egp: d.subtotal,
    delivery_egp: d.delivery,
    total_egp: d.total,
    fulfilment: d.fulfilment,
    address: d.address,
    status: 'new',
    updated_at: d.now
  }
}];

const d = $('Decide Reply').first().json;
return [{
  json: {
    customer_id: d.sender_id,
    platform: d.platform,
    items_json: '[]',
    fulfilment: '',
    address: '',
    total_egp: 0,
    status: 'closed',
    updated_at: d.now
  }
}];

const d = $('Decide Reply').first().json;
return [{
  json: {
    customer_id: d.sender_id,
    platform: d.platform,
    items_json: d.items_json,
    fulfilment: d.fulfilment,
    address: d.address,
    total_egp: d.total,
    status: 'open',
    updated_at: d.now
  }
}];

const d = $('Decide Reply').first().json;
return [{
  json: {
    customer_id: d.sender_id,
    platform: d.platform,
    items_json: '[]',
    fulfilment: '',
    address: '',
    total_egp: 0,
    status: 'closed',
    updated_at: d.now
  }
}];

